from rosterkit.errors import ProjectError

def _sort_key(pupil):
    return (pupil.last_name, pupil.first_name)

def _label(pupil):
    return f"{pupil.last_name}, {pupil.first_name}"

def _row_line(ordered, seats, slot):
    group = ordered[slot * seats:(slot + 1) * seats]
    names = " | ".join(_label(pupil) for pupil in group)
    return f"Row {slot + 1}: {names}"

def seat_rows(students, seats):
    if seats <= 0 or not students:
        raise ProjectError("need students and seats")
    ordered = sorted(students, key=_sort_key)
    count = -(-len(ordered) // seats)
    return [
        _row_line(ordered, seats, slot) for slot in range(count)
    ]

